				const source: Pokemon = this.effectState.source;
				this.debug('Pursuit start');
				if (
					!source.isAdjacent(pokemon) || !source.hp ||
					(source.volatiles['encore'] && source.volatiles['encore'].move !== 'pursuit') ||
					!this.queue.cancelMove(source)
